# 1. Arguments that the extractor may provide to the policy
list_of_arguments_to_read = {
    # always present
    "tool_name": str,

    # arguments for each tool
    "user_id": str,                     # check_user_risk_level
    "risk_level": str,                  # recommend_portfolio (requested level)
    "ticker": str,                      # get_stock_info
    "keyword": str,                     # search_market_news
    "limit": int,                       # search_market_news (optional)
    "conversation_id": str,             # flag_compliance_issue
    "reason": str,                      # flag_compliance_issue
    "severity": str,                    # flag_compliance_issue (optional)

    # results of previous tool calls in the same episode (prefixed with the tool name)
    "check_user_risk_level_status": str,   # "success" / "error"
    "check_user_risk_level_level": str,    # C1‑C5
    "check_user_risk_level_timestamp": str, # opaque timestamp string (if available)

    "get_stock_info_is_st": bool,          # true if the last queried stock is ST
    "get_stock_info_risk_rating": str,     # R1‑R5 of the last queried stock

    # history flags
    "recommend_portfolio_called": bool,    # True if recommend_portfolio has already been called
    "recommend_portfolio_last_check_level": str,  # risk level used in the last portfolio call
    "recommend_portfolio_last_check_timestamp": str, # timestamp of the check that preceded the last call
}

# 2. Constants used by the policy
ALLOWED_READ_ONLY_TOOLS = {
    "check_user_risk_level",
    "get_stock_info",
    "search_market_news",
    "flag_compliance_issue",
}
HIGH_RISK_TOOL = "recommend_portfolio"

# Mapping of user risk level to the highest product risk rating they may receive
# (C1 can only get R1, C2 up to R2, … C5 up to R5)
USER_MAX_PRODUCT_RISK = {
    "C1": "R1",
    "C2": "R2",
    "C3": "R3",
    "C4": "R4",
    "C5": "R5",
}

# Ordered risk ratings for comparison
RISK_ORDER = {"R1": 1, "R2": 2, "R3": 3, "R4": 4, "R5": 5}
LEVEL_ORDER = {"C1": 1, "C2": 2, "C3": 3, "C4": 4, "C5": 5}


def _risk_not_exceed(user_level: str, requested_level: str) -> bool:
    """Return True if requested_level (C‑level) is <= user_level."""
    return LEVEL_ORDER.get(requested_level, 0) <= LEVEL_ORDER.get(user_level, 0)


def _product_risk_allowed(user_level: str, product_risk: str) -> bool:
    """Return True if product_risk (R‑level) is within the band allowed for user_level."""
    max_allowed = USER_MAX_PRODUCT_RISK.get(user_level)
    if max_allowed is None:
        return False
    return RISK_ORDER.get(product_risk, 0) <= RISK_ORDER.get(max_allowed, 0)


def policy(arguments: dict) -> tuple[bool, str]:
    """Allow or deny a tool call based on risk‑level verification and usage rules."""
    tool = arguments.get("tool_name")
    if tool is None:
        return False, "Missing tool_name."

    # Always allow read‑only tools
    if tool in ALLOWED_READ_ONLY_TOOLS:
        return True, f"Tool '{tool}' is read‑only and always allowed."

    # From here on we are dealing with the high‑risk tool
    if tool != HIGH_RISK_TOOL:
        # Any tool not explicitly listed as always allowed is permitted by default
        return True, f"Tool '{tool}' not covered by policy, allowing by default."

    # ---------- High‑risk tool: recommend_portfolio ----------
    # 1. Verify a prior successful risk check exists
    check_status = arguments.get("check_user_risk_level_status")
    user_level = arguments.get("check_user_risk_level_level")
    if not check_status or not user_level:
        return False, "Missing prior check_user_risk_level result; cannot verify user risk."

    if check_status.lower() != "success":
        return False, f"Prior risk check failed (status={check_status}); cannot call {HIGH_RISK_TOOL}."

    # 2. Ensure the risk_level argument matches the verified user level
    requested_level = arguments.get("risk_level")
    if not requested_level:
        return False, "Missing required argument 'risk_level' for recommend_portfolio."

    if requested_level != user_level:
        return False, (
            f"Requested risk_level '{requested_level}' does not match verified user level "
            f"'{user_level}'."
        )

    # 3. Ensure the requested level does not exceed the user's actual level
    if not _risk_not_exceed(user_level, requested_level):
        return False, (
            f"Requested risk_level '{requested_level}' exceeds user's verified level '{user_level}'."
        )

    # 4. Enforce one‑call‑per‑check rule
    already_called = arguments.get("recommend_portfolio_called", False)
    if already_called:
        # Require a fresh risk check (timestamp comparison is optional; we just require a new check)
        # If the last check timestamp is the same as the one that preceded the previous call,
        # we consider it not fresh.
        last_check_ts = arguments.get("check_user_risk_level_timestamp")
        last_portfolio_check_ts = arguments.get(
            "recommend_portfolio_last_check_timestamp"
        )
        if last_check_ts and last_portfolio_check_ts and last_check_ts == last_portfolio_check_ts:
            return False, (
                "recommend_portfolio has already been called after the most recent "
                "check_user_risk_level; a new risk check is required."
            )
        # If timestamps are unavailable, be conservative and deny
        if not last_check_ts or not last_portfolio_check_ts:
            return False, (
                "Unable to verify a fresh risk check before a second recommend_portfolio call."
            )

    # 5. Verify that any high‑risk stock information previously retrieved is compatible
    #    with the user's level. If the last queried stock is ST or R5, only C5 users may
    #    receive a portfolio that could include it.
    is_st = arguments.get("get_stock_info_is_st")
    stock_risk = arguments.get("get_stock_info_risk_rating")
    if is_st or (stock_risk == "R5"):
        if user_level != "C5":
            return False, (
                "High‑risk stock (ST or R5) was queried, but user level is not C5; "
                "cannot generate portfolio containing such products."
            )

    # All checks passed
    return True, "All risk‑level checks passed; recommend_portfolio allowed."

