    "statement": "IF tool_name = \"recommend_portfolio\" AND get_stock_info_risk_rating IS NOT NULL AND NOT _product_risk_allowed(check_user_risk_level_level, get_stock_info_risk_rating) THEN return (allow = false, reason = \"stock risk rating exceeds the maximum allowed for the user level\")."
  },
